CREATE POLICY generated_assets_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='generated-assets' AND EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id::text=(storage.foldername(name))[1] AND user_id=auth.uid()));
CREATE POLICY originals_workspace_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='original-files' AND EXISTS(SELECT 1 FROM public.files WHERE storage_path=name AND public.is_workspace_member(workspace_id)));
CREATE FUNCTION public.validate_storage_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.reclaimed_size_bytes>0 AND (NEW.retention_verified_at IS NULL OR NEW.approval_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.id=NEW.approval_id AND a.workspace_id=NEW.workspace_id AND a.file_id=NEW.file_id AND a.status='Approved')) THEN RAISE EXCEPTION 'Reclaimed storage requires verified authorized approval'; END IF; RETURN NEW; END $$;
CREATE TRIGGER storage_verification BEFORE INSERT OR UPDATE ON public.storage_analytics FOR EACH ROW EXECUTE FUNCTION public.validate_storage_verification();